import{_ as o,l as i,o as e,c as n,v as t,p as d,x as r,d as l,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"快速重传与恢复","description":"","frontmatter":{"title":"快速重传与恢复","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fast-retransmit-recovery.md","filePath":"cs/fast-retransmit-recovery.md","lastUpdated":1789023840000}'),A={name:"cs/fast-retransmit-recovery.md"};function h(C,a,u,m,_,f){const s=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="快速重传与恢复" tabindex="-1">快速重传与恢复 <a class="header-anchor" href="#快速重传与恢复" aria-label="Permalink to &quot;快速重传与恢复&quot;">​</a></h1><div class="epigraph"><p>三个重复 ACK 推断丢包并立刻重传，快恢复用减半后的窗口继续发，避免慢启动把管道抽空。</p><footer>—— 据 RFC 5681；Jacobson, 1988；主干 Reno 课整理</footer></div><p><a href="/cs/aimd-dynamics">上一课</a> 给出减半几何。主干<a href="/cs/tcp-seq-rexmit">序号与重传</a>、<a href="/cs/tcp-sack">SACK</a> 已有。缺口是<strong>快重传/快恢复与超时的分工</strong>：dupACK 计数、inflate 窗口、incast 短流为何仍只能等 RTO。本课不把 BDP 公式写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>超时把 ssthresh 记下再把 cwnd 抽到很小。若只丢一包且后续包仍到，收端每包回 dupACK。满三个：重传丢失包，进入快恢复：cwnd ≈ FlightSize/2，每额外 dupACK 可再发新数据（Reno inflate）。SACK 让恢复知道洞在哪，避免重传已到的段。三个 dupACK 要管道里还有包，BDP 太小或短流则失败——incast 场景。</p><p>不要把快重传写成「永远不必超时」。</p><p><span class="marginnote">RFC 5681。NewReno 修部分 ACK。本课不把每家内核的 RACK 写完，后课可点名。</span></p><h3 id="三个-dupack-才走快路径" tabindex="-1">三个 dupACK 才走快路径 <a class="header-anchor" href="#三个-dupack-才走快路径" aria-label="Permalink to &quot;三个 dupACK 才走快路径&quot;">​</a></h3><p>快恢复避免抽空管道。短流/浅管道仍可能只能 RTO。乱序会产生伪 dupACK。SACK 告诉洞在哪。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：RTO 路径 vs 快重传路径。画：dupACK++ → 3 → 重传 → 快恢复 → 新 ACK 退出。与 DCTCP：标记不走这条丢包路径。</p>',11)),(e(),d(c,null,{default:r(()=>[p(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DUP%5B%22%E9%87%8D%E5%A4%8D%20ACK%22%5D%20--%3E%20FR%5B%22%E5%BF%AB%E9%87%8D%E4%BC%A0%22%5D%0A%20%20FR%20--%3E%20FRV%5B%22%E5%BF%AB%E6%81%A2%E5%A4%8D%22%5D%0A%20%20FRV%20--%3E%20CA%5B%22%E5%9B%9E%E5%88%B0%E6%8B%A5%E5%A1%9E%E9%81%BF%E5%85%8D%22%5D%0A%20%20TO%5B%22%E8%B6%85%E6%97%B6%22%5D%20--%3E%20SS%5B%22%E6%85%A2%E5%90%AF%E5%8A%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AIMD 的 MD 在快恢复里发生，不是在慢启动。ECMP 乱序会产生伪 dupACK，要用 FACK/RACK 或乱序阈。RoCE 无这条状态机。卫星误码触发假拥塞 MD，RFC 2488 的痛。</p><p>SACK 是信息，快恢复是控制；两者配套。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BBR 探测的全部。带宽时延积是下一课。后课默认：三个 dupACK 走快路径；否则 RTO。</p><p>重复 ACK 阈固定为 3 是历史折中，不是信息论最优。</p><p>上一课留下的缺口在本课收口；「快速重传与恢复」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/bandwidth-delay-product">带宽时延积</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>快重传用 dupACK 推断丢包。</li><li>快恢复避免抽空管道。</li><li>短流/浅管道仍可能只能 RTO。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 5681；Jacobson, 1988。</li></ul>',10))])}const R=o(A,[["render",h]]);export{B as __pageData,R as default};
